import{_ as a,c as i,o,ae as l}from"./chunks/framework.DI6M9D4h.js";const r="/assets/3w6-split-keyboard-kit-black-pcb-2.CChRAcHV.jpg",s="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-12.CHsnL280.jpg",d="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-10.CK8PBGLY.jpg",n="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-11.C2p0Bqwi.jpg",h="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-1.DhpmA32T.jpg",p="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-3.9XG8rgvS.jpg",e="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-4.DHjq0Hg5.jpg",c="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-5.D8p-3UfX.jpg",m="/assets/3w6-split-keyboard-kit-black-pcb-build-guide-7.C0wwwqOS.jpg",b="/assets/3w6-pimoroni-trackball-1.BJu02Yjy.jpg",u="/assets/3w6-pimoroni-trackball-2.CAwIiZoq.jpg",g="/assets/3w6-pimoroni-trackball-3.C2CiGwHk.jpg",f="/assets/3w6-pimoroni-trackball-4.BiQqaCFK.jpg",k="/assets/3w6-rp2040-schematic-1.DXP0kgQD.png",B=JSON.parse('{"title":"3w6-2040 Build Guide","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/3w6/index.md","filePath":"build-guides/3w6/index.md","lastUpdated":1786007404000}'),y={name:"build-guides/3w6/index.md"};function w(_,t,C,q,P,v){return o(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_3w6-2040-build-guide" tabindex="-1">3w6-2040 Build Guide <a class="header-anchor" href="#_3w6-2040-build-guide" aria-label="Permalink to &quot;3w6-2040 Build Guide&quot;">​</a></h1><p><a href="https://github.com/firstcontributions/first-contributions" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="PRs Welcome" loading="lazy"></a><a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a><a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-CC%20BY--NC--SA%204.0-lightgrey.svg?style=flat-square" alt="License: CC BY-NC-SA 4.0" loading="lazy"></a></p><h2 id="bom" tabindex="-1">BOM <a class="header-anchor" href="#bom" aria-label="Permalink to &quot;BOM&quot;">​</a></h2><h3 id="parts-included-in-the-kit" tabindex="-1">Parts included in the kit <a class="header-anchor" href="#parts-included-in-the-kit" aria-label="Permalink to &quot;Parts included in the kit&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Part name</th><th style="text-align:left;">Qty</th><th style="text-align:left;">Remarks</th></tr></thead><tbody><tr><td style="text-align:left;">Top plates</td><td style="text-align:left;">2</td><td style="text-align:left;">Nr. 1 on the image below</td></tr><tr><td style="text-align:left;">Spacer plates</td><td style="text-align:left;">2</td><td style="text-align:left;">Nr. 2 on the image below, 3D printed PLA</td></tr><tr><td style="text-align:left;">PCB&#39;s</td><td style="text-align:left;">2</td><td style="text-align:left;">Nr. 3 on the image below</td></tr><tr><td style="text-align:left;">Foam</td><td style="text-align:left;">2</td><td style="text-align:left;">Nr. 4 on the image below, self-adhesive</td></tr></tbody></table><p><img src="'+r+'" alt="Kit parts" loading="lazy"></p><h3 id="additionally-required-parts" tabindex="-1">Additionally required parts <a class="header-anchor" href="#additionally-required-parts" aria-label="Permalink to &quot;Additionally required parts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Part name</th><th>Qty</th><th>Remarks</th></tr></thead><tbody><tr><td>Choc V1 switches</td><td>36</td><td>Choc V2 switches are <strong>not</strong> supported</td></tr><tr><td>1U Choc keycaps (Lo Profile)</td><td>34</td><td>MX keycaps are <strong>not</strong> supported</td></tr><tr><td>1.5U Choc keycaps (Lo Profile)</td><td>2</td><td>MX keycaps are <strong>not</strong> supported</td></tr><tr><td>USB-C cable</td><td>1</td><td>To connect the keyboard to your computer</td></tr><tr><td>USB-C to USB-C cable</td><td>1</td><td>To connect both halfs, 20cm lenght is good</td></tr></tbody></table><h3 id="optional-parts" tabindex="-1">Optional parts <a class="header-anchor" href="#optional-parts" aria-label="Permalink to &quot;Optional parts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Part name</th><th>Qty</th><th>Remarks</th></tr></thead><tbody><tr><td>Pimoroni Trackball module</td><td>1</td><td>Support on both half&#39;s simultaneously, or only one side</td></tr></tbody></table><h2 id="cad-files" tabindex="-1">CAD files <a class="header-anchor" href="#cad-files" aria-label="Permalink to &quot;CAD files&quot;">​</a></h2><ul><li>Top plate <a href="https://github.com/Keycapsss/keycapsss-help-site/blob/master/docs/build-guides/3w6/cad/3w6-2040-plate-top.dxf" target="_blank" rel="noreferrer">dxf file</a></li></ul><h2 id="initial-test" tabindex="-1">Initial test <a class="header-anchor" href="#initial-test" aria-label="Permalink to &quot;Initial test&quot;">​</a></h2><p>All PCB&#39;s are tested and the VIAL QMK firmware is already flashed on both sides.</p><p>I recommend to test each switch position for functionality, before you solder the switches.</p><p>Connect both half&#39;s with a USB-C to USB-C cable and connect one side with a USB-C cable to your computer.</p><blockquote><p>The pre flashed firmware use <a href="https://docs.qmk.fm/#/feature_split_keyboard?id=handedness-by-eeprom" target="_blank" rel="noreferrer">&quot;Handedness by EEPROM&quot;</a>, so it does not matter which half is master (connected to the computer). The layout can be mirrored if &quot;Handedness by EEPROM&quot; is not used.</p></blockquote><p>Open <a href="https://config.qmk.fm/#/test" target="_blank" rel="noreferrer">QMK Configurator page</a> and bridge each switch solder point pair with a tweezers. It should trigger a key press. If not please contact me.</p><p><img src="'+s+'" alt="alt" loading="lazy"><img src="'+d+'" alt="alt" loading="lazy"></p><h2 id="visual-enhancement-optional" tabindex="-1">Visual enhancement (optional) <a class="header-anchor" href="#visual-enhancement-optional" aria-label="Permalink to &quot;Visual enhancement (optional)&quot;">​</a></h2><p>This step is not necessary, but will improve visually appealing of your 3W6 split keyboard.</p><p>Due to the manufacturing process of the PCB&#39;s, there are some rough edges. Use a small file to remove these marks (mouse bites).</p><p>You could also paint the edges black with a black Sharpie/Edding.</p><p><img src="'+n+'" alt="3W6 paint PCB edges black and remove mouse bites" loading="lazy"></p><h2 id="assembly" tabindex="-1">Assembly <a class="header-anchor" href="#assembly" aria-label="Permalink to &quot;Assembly&quot;">​</a></h2><p>Attach the Choc V1 switches (36x) to the top plates and pay attention to the switch orientation. The lower row has a different orientation.</p><p>Check carefully if all switch pins are staight.</p><p><img src="'+h+'" alt="3w6 top plate with switches from bottom view" loading="lazy"></p><p>Put the 3D printed spacer on the back of the top plate.</p><p><img src="'+p+'" alt="3w6 3d printed spacer plates on top of the PCB&#39;s" loading="lazy"></p><p>Place the pcb (SMD components must face down) on the top plate with the switches spacer. Do not press to hard. Check if all switch pins are align with the holes in the PCB.</p><p><img src="'+e+'" alt="alt" loading="lazy"></p><p>If all switch pins are aligned, press the top plate and the PCB together. If you have problems to close the gap, probably a switch pin is bent.</p><p><img src="'+c+'" alt="alt" loading="lazy"></p><p>While you press the PCB down, solder all switch pin&#39;s (green marked)</p><p><img src="'+e+'" alt="alt" loading="lazy"></p><p>Connect both half&#39;s with a USB-C to USB-C cable and connect one half with a USB-C cable to your computer.</p><p>Open <a href="https://config.qmk.fm/#/test" target="_blank" rel="noreferrer">QMK Configurator page</a> and test if all switches trigger a key press. If not check the corresponding solder point for the switch.</p><p>If everything works as expected, you can attach the self-adhesive foam to the underside.</p><p>The complete assembled 3W6 Split Keyboard should have 4 layers <em>The self-adhesive protection foil was not removed for demonstration purpose.</em></p><p><img src="'+m+'" alt="alt" loading="lazy"></p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p>The <a href="https://get.vial.today" target="_blank" rel="noreferrer">VIAL QMK firmware</a> with the <a href="https://github.com/vial-kb/vial-qmk/tree/vial/keyboards/keycapsss/3w6_2040/keymaps/vial" target="_blank" rel="noreferrer">vial keymap</a> is already flashed on both half&#39;s.</p><p>To customize the layout of your 3W6, <a href="https://get.vial.today/download/" target="_blank" rel="noreferrer">download</a> the VIAL GUI, or use the <a href="https://vial.rocks/" target="_blank" rel="noreferrer">web version</a>. The keyboard should be detected right out of the box.</p><h3 id="customize-the-firmware-optional" tabindex="-1">Customize the firmware (optional) <a class="header-anchor" href="#customize-the-firmware-optional" aria-label="Permalink to &quot;Customize the firmware (optional)&quot;">​</a></h3><p>With the command below, you compile the vial keymap for the 3w6 <a href="https://docs.qmk.fm/#/newbs" target="_blank" rel="noreferrer">(after setting up your build environment)</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/3w6_2040:vial:uf2-split-right</span></span></code></pre></div><p>You will find a <code>keycapsss_3w6_2040_vial.uf2</code> in the qmk folder. Rename it to <code>keycapsss_3w6_2040_vial_right.uf2</code> and do the same for the left firmware file (replace <code>right</code> with <code>left</code>).</p><h3 id="bootloader-flash-firmware" tabindex="-1">Bootloader (flash firmware) <a class="header-anchor" href="#bootloader-flash-firmware" aria-label="Permalink to &quot;Bootloader (flash firmware)&quot;">​</a></h3><ol><li>Push and hold the BOOTSEL button and connect the half to the computer.</li><li>A mass storage drive (RPI-RP2) should appear. You can release the BOOTSEL button.</li><li>Drag and drop the UF2 file onto the RPI-RP2 volume. The 3W6 will reboot.</li></ol><h2 id="pimoroni-trackball" tabindex="-1">Pimoroni Trackball <a class="header-anchor" href="#pimoroni-trackball" aria-label="Permalink to &quot;Pimoroni Trackball&quot;">​</a></h2><p>This 3W6 keyboard supports a trackball module on both sides (left side only, right side only, or on both sides simultaneously).</p><p>The trackball module is already activated in the default flashed firmware.</p><p>The trackball is connected via I2C to the mcu. Since Rev1.1 the INT (interrupt pin) is connected to the GPIO24 pin. Right now <em>(05.2023)</em> the QMK <a href="https://docs.qmk.fm/#/feature_pointing_device?id=pimoroni-trackball" target="_blank" rel="noreferrer">driver for the Pimoroni Trackball module</a> do not use the INT pin.</p><h3 id="trackball-module-assembly" tabindex="-1">Trackball module assembly <a class="header-anchor" href="#trackball-module-assembly" aria-label="Permalink to &quot;Trackball module assembly&quot;">​</a></h3><ol><li><p>Solder the header pin to the module (plastic part at the bottom). Carefully remove the plastic from the header pins (marked red) with pliers.</p><p><img src="'+b+'" alt="alt" loading="lazy"></p></li><li><p>On the side you want to install the trackball module, break away the red marked part. There is a predetermined breaking point at the vertical red line.</p><p><img src="'+u+'" alt="alt" loading="lazy"></p></li><li><p>Place the module on the top side of the pcb. The module should sit on the pcb, without a gap (green arrow). The module should be align with the white tactile switch next to it. If not, it could be that the plastic cover of the trackball do not fit in the cutout in the top plate. Solder the header pins from the bottom.</p><p><img src="'+g+'" alt="alt" loading="lazy"></p></li><li><p>Cut the header pins as close as possible to the pcb and reflow the solder points again (looks better).</p><p><img src="'+f+'" alt="alt" loading="lazy"><em>Ignore the pixelated part, it&#39;s from a prototype.</em></p></li></ol><h2 id="schematic" tabindex="-1">Schematic <a class="header-anchor" href="#schematic" aria-label="Permalink to &quot;Schematic&quot;">​</a></h2><p><a href="https://github.com/Keycapsss/3w6/raw/master/img/3w6-rp2040-schematic-1.png" target="_blank" rel="noreferrer"><img src="'+k+'" alt="3W6 schematic" loading="lazy"></a><em>Schematic for the RP2040 part (right side is equal)</em></p>',58)])])}const T=a(y,[["render",w]]);export{B as __pageData,T as default};
